mapper.select:
select  from order_profit_ledger opl
LEFT JOIN merchant m ON opl.merchant_id = m.id
LEFT JOIN distributor d ON opl.distributor_id = d.id

    opl.del_flag = '0'
    and opl.merchant_id = #{merchantId}
    and opl.distributor_id = #{distributorId}
    and opl.order_no = #{orderNo}
    and opl.status = #{status}


order by opl.create_time desc

mapper.update:
update order_profit_ledger
status = #{status}, profit_sharing_attempts = #{profitSharingAttempts}, profit_sharing_last_attempt_time = #{profitSharingLastAttemptTime}, profit_sharing_next_retry_time = #{profitSharingNextRetryTime}, profit_sharing_out_order_no = #{profitSharingOutOrderNo}, profit_sharing_order_id = #{profitSharingOrderId}, remark = #{remark},
where id = #{id}

update order_profit_ledger
set profit_sharing_attempts = COALESCE(profit_sharing_attempts, 0) + 1,
    profit_sharing_last_attempt_time = NOW(),
    profit_sharing_next_retry_time = #{nextRetryTime}
where id = #{id}
  and del_flag = '0'
  and status in ('WAITING_SETTLEMENT', 'WECHAT_PROFIT_SHARING_FAILED')
  and COALESCE(profit_sharing_attempts, 0) < #{maxAttempts}
  and (profit_sharing_next_retry_time is null or profit_sharing_next_retry_time <= NOW())

update order_profit_ledger
set profit_sharing_out_order_no = #{outOrderNo}
where id = #{id} and del_flag = '0'

update order_profit_ledger set status = #{status}, remark = #{remark}, profit_sharing_order_id = #{orderId}, profit_sharing_next_retry_time =
NULL #{nextRetryTime}
where id = #{id} and del_flag = '0'
